                   ISNULL(NroOperacion, '') AS NroOperacion, ISNULL(Usuario, '') AS Usuario,
                   ISNULL(PagoTotal, 0) AS Total
              FROM PagoVarios
             WHERE PagoId = @PagoId;
            """, con))
        {
            pagoCmd.Parameters.AddWithValue("@PagoId", pagoId);
            await using var reader = await pagoCmd.ExecuteReaderAsync(cancellationToken);
            if (await reader.ReadAsync(cancellationToken))
            {
                pago = new PagoVariosHistorialItemResponse
                {
                    PagoId = Convert.ToInt64(reader["PagoId"], CultureInfo.InvariantCulture),
                    CajaId = Convert.ToInt64(reader["CajaId"], CultureInfo.InvariantCulture),
                    FechaEmision = reader["FechaEmision"]?.ToString() ?? string.Empty,
                    Descripcion = reader["Descripcion"]?.ToString() ?? string.Empty,
                    FormaPago = reader["FormaPago"]?.ToString() ?? string.Empty,
                    Entidad = reader["Entidad"]?.ToString() ?? string.Empty,
                    Efectivo = Convert.ToDecimal(reader["Efectivo"], CultureInfo.InvariantCulture),
                    Deposito = Convert.ToDecimal(reader["Deposito"], CultureInfo.InvariantCulture),
                    NroOperacion = reader["NroOperacion"]?.ToString() ?? string.Empty,
                    Usuario = reader["Usuario"]?.ToString() ?? string.Empty,
                    Total = Convert.ToDecimal(reader["Total"], CultureInfo.InvariantCulture)
                };
            }
        }

        if (pago is null)
            return NotFound(new { ok = false, mensaje = "No se encontró el pago realizado." });

        var items = new List<PagoVariosDetalleItemResponse>();
        await using (var detalleCmd = new SqlCommand("""
            SELECT dp.DocuId, dp.NotaId, ISNULL(d.DocuSerie, '') AS Serie,
                   ISNULL(d.DocuNumero, '') AS Numero, ISNULL(c.ClienteCodigo, '') AS Codigo,
                   ISNULL(c.ClienteRazon, '') AS RazonSocial, ISNULL(dp.Monto, 0) AS Monto,
                   ISNULL(dp.ConceptoOBS, '') AS ConceptoOBS, ISNULL(dp.Efectivo, 0) AS Efectivo,
                   ISNULL(dp.Deposito, 0) AS Deposito
              FROM DetallePVarios dp
              LEFT JOIN DocumentoVenta d ON d.DocuId = dp.DocuId
              LEFT JOIN NotaPedido n ON n.NotaId = dp.NotaId
              LEFT JOIN Cliente c ON c.ClienteId = n.ClienteId
             WHERE dp.PagoId = @PagoId
             ORDER BY dp.NotaId;
            """, con))
        {
            detalleCmd.Parameters.AddWithValue("@PagoId", pagoId);
            await using var reader = await detalleCmd.ExecuteReaderAsync(cancellationToken);
            while (await reader.ReadAsync(cancellationToken))
            {
                var serie = reader["Serie"]?.ToString()?.Trim() ?? string.Empty;
                var numero = reader["Numero"]?.ToString()?.Trim() ?? string.Empty;
                items.Add(new PagoVariosDetalleItemResponse
                {
                    DocuId = Convert.ToInt64(reader["DocuId"], CultureInfo.InvariantCulture),
                    NotaId = Convert.ToInt64(reader["NotaId"], CultureInfo.InvariantCulture),
                    Documento = string.Join("-", new[] { serie, numero }.Where(x => x.Length > 0)),
                    Codigo = reader["Codigo"]?.ToString()?.Trim() ?? string.Empty,
                    RazonSocial = reader["RazonSocial"]?.ToString()?.Trim() ?? string.Empty,
                    Monto = Convert.ToDecimal(reader["Monto"], CultureInfo.InvariantCulture),
                    ConceptoOBS = reader["ConceptoOBS"]?.ToString()?.Trim() ?? string.Empty,
                    Efectivo = Convert.ToDecimal(reader["Efectivo"], CultureInfo.InvariantCulture),
                    Deposito = Convert.ToDecimal(reader["Deposito"], CultureInfo.InvariantCulture)
                });
            }
        }

        return Ok(new { ok = true, pago, items });
    }

[AllowAnonymous]
    [HttpDelete("pago-varios/{pagoId:long}", Name = "DeletePagoVarios")]
    [ProducesResponseType((int)HttpStatusCode.OK)]
    public async Task<IActionResult> EliminarPagoVarios(
        long pagoId,
        [FromBody] EliminarPagoVariosRequest request,
        CancellationToken cancellationToken = default)
    {
        if (pagoId <= 0)
            return BadRequest(new { ok = false, mensaje = "Pago Varios inválido." });

        var clave = (request?.Clave ?? string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(clave))
            return BadRequest(new { ok = false, mensaje = "Ingrese la clave de administrador." });

        await using var con = new SqlConnection(_configuration.GetConnectionString("DefaultConnection"));
        await con.OpenAsync(cancellationToken);

        await using (var validarClave = new SqlCommand("""
            SELECT TOP (1) 1
              FROM Usuarios
             WHERE dbo.desincrectar(UsuarioClave) = @Clave
               AND Administrador = 1;
            """, con))
        {
            validarClave.Parameters.AddWithValue("@Clave", clave);
            if (await validarClave.ExecuteScalarAsync(cancellationToken) is null)
                return Unauthorized(new { ok = false, mensaje = "Clave de administrador inválida." });
        }

        var detalles = new List<(long DocuId, long NotaId)>();
        await using (var listarDetalles = new SqlCommand("""
            SELECT DocuId, NotaId
              FROM DetallePVarios
             WHERE PagoId = @PagoId
             ORDER BY PagoId;
            """, con))
        {
            listarDetalles.Parameters.AddWithValue("@PagoId", pagoId);
            await using var reader = await listarDetalles.ExecuteReaderAsync(cancellationToken);
            while (await reader.ReadAsync(cancellationToken))
            {
                detalles.Add((
                    Convert.ToInt64(reader["DocuId"], CultureInfo.InvariantCulture),
                    Convert.ToInt64(reader["NotaId"], CultureInfo.InvariantCulture)
                ));
            }
        }

        if (detalles.Count == 0)
            return NotFound(new { ok = false, mensaje = "No se encontró el pago realizado." });

        var listaOrden = $"{pagoId}[{string.Join(";", detalles.Select(x => $"{x.DocuId}|{x.NotaId}"))}";
        await using var eliminar = new SqlCommand("uspEliminarPagoVWEB", con)
        {
            CommandType = CommandType.StoredProcedure
        };
        eliminar.Parameters.Add("@ListaOrden", SqlDbType.VarChar, -1).Value = listaOrden;
        var resultado = (await eliminar.ExecuteScalarAsync(cancellationToken))?.ToString()?.Trim();

        if (!string.Equals(resultado, "true", StringComparison.OrdinalIgnoreCase))
            return BadRequest(new { ok = false, mensaje = "No se pudo eliminar el pago realizado." });

        return Ok(new { ok = true, mensaje = "Pago realizado eliminado." });
    }

[AllowAnonymous]
    [HttpPost("pago-varios", Name = "RegisterPagoVarios")]
    [ProducesResponseType((int)HttpStatusCode.OK)]
    public async Task<IActionResult> RegistrarPagoVarios(
        [FromBody] RegistrarPagoVariosRequest request,
        CancellationToken cancellationToken = default)
    {
        if (request is null || request.UsuarioId <= 0)
            return BadRequest(new { ok = false, mensaje = "usuarioId es requerido." });
        if (request.Detalles is null || request.Detalles.Count == 0)
            return BadRequest(new { ok = false, mensaje = "Seleccione documentos para pagar." });

        var concepto = (request.ConceptoOBS ?? string.Empty).Trim().ToUpperInvariant();
        if (string.IsNullOrWhiteSpace(concepto))
            concepto = (request.Detalles[0].ConceptoOBS ?? string.Empty).Trim().ToUpperInvariant();
        if (request.Detalles.Any(x => !string.Equals((x.ConceptoOBS ?? string.Empty).Trim(), concepto, StringComparison.OrdinalIgnoreCase)))
            return BadRequest(new { ok = false, mensaje = "Seleccione documentos con el mismo concepto OBS." });

        var total = request.Detalles.Sum(x => x.Monto);
        var formaPago = (request.FormaPago ?? "EFECTIVO").Trim().ToUpperInvariant();
        var efectivo = formaPago == "EFECTIVO" ? total : Math.Max(0, request.Efectivo);
        var deposito = formaPago == "EFECTIVO" ? 0 : Math.Max(0, request.Deposito);
        if (formaPago != "EFECTIVO" && deposito <= 0)
            deposito = total - efectivo;
        if (Math.Round(efectivo + deposito, 2) != Math.Round(total, 2))
            return BadRequest(new { ok = false, mensaje = "Efectivo + deposito debe cuadrar con el total." });

        var header = string.Join("|", new[]
        {
            "0",
            DateTime.Now.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture),
            formaPago,
            (request.Entidad ?? "-").Trim(),
            efectivo.ToString("0.00", CultureInfo.InvariantCulture),
            deposito.ToString("0.00", CultureInfo.InvariantCulture),
            (request.NroOperacion ?? string.Empty).Trim(),
            (request.Descripcion ?? "PAGO VARIOS").Trim().ToUpperInvariant(),
            (request.Usuario ?? "USUARIO").Trim(),
            request.UsuarioId.ToString(CultureInfo.InvariantCulture),
            concepto,
            total.ToString("0.00", CultureInfo.InvariantCulture),
            (request.Image ?? string.Empty).Trim()
        });

        var efectivoPendiente = efectivo;
        var depositoPendiente = deposito;
        var detalles = string.Join(";", request.Detalles.Select(d =>
        {
            var monto = d.Monto;
            var efectivoDetalle = Math.Min(monto, efectivoPendiente);
            var depositoDetalle = monto - efectivoDetalle;
            efectivoPendiente -= efectivoDetalle;
            depositoPendiente -= depositoDetalle;
            if (depositoPendiente < 0) depositoPendiente = 0;
            return string.Join("|", new[]
            {
                d.DocuId.ToString(CultureInfo.InvariantCulture),
                d.NotaId.ToString(CultureInfo.InvariantCulture),
                monto.ToString("0.00", CultureInfo.InvariantCulture),
                concepto,
                efectivoDetalle.ToString("0.00", CultureInfo.InvariantCulture),
                depositoDetalle.ToString("0.00", CultureInfo.InvariantCulture)
            });
        }));

        await using var con = new SqlConnection(_configuration.GetConnectionString("DefaultConnection"));
        await using var cmd = new SqlCommand("uspInsertarPagoVariosWEB", con)
        {
            CommandType = CommandType.StoredProcedure
        };
        cmd.Parameters.AddWithValue("@ListaOrden", $"{header}[{detalles};");

        await con.OpenAsync(cancellationToken);
        var raw = (await cmd.ExecuteScalarAsync(cancellationToken))?.ToString()?.Trim() ?? string.Empty;
        if (string.Equals(raw, "true", StringComparison.OrdinalIgnoreCase))
        {
            await CerrarSaldosPagoVariosAsync(con, null, request.Detalles, cancellationToken);
            return Ok(new { ok = true, resultado = raw });
        }
        if (string.Equals(raw, "false", StringComparison.OrdinalIgnoreCase))
        {
            return Conflict(new
            {
                ok = false,
                codigo = "CAJA_CHICA_CERRADA",
                resultado = raw,
                mensaje = "No se aperturó caja chica. Favor de abrir una nueva caja."
            });
        }
        if (string.Equals(raw, "OPERACION", StringComparison.OrdinalIgnoreCase))
            return BadRequest(new { ok = false, codigo = "OPERACION", resultado = raw, mensaje = "El numero de operacion ya existe." });

        return Ok(new { ok = false, resultado = raw, mensaje = raw });
    }

