private static string ResolverRutaPfx(string rutaPfx)
    {
        var valor = (rutaPfx ?? string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(valor))
        {
            return valor;
        }

        if (!TryObtenerBytesDesdeBase64(valor, out var bytesPfx))
        {
            return ResolverRutaPfxDesdeArchivoOCarpeta(valor);
        }

        var directorioCertificados = ObtenerDirectorioCertificados();
        Directory.CreateDirectory(directorioCertificados);
        var fileName = $"cert_{DateTime.UtcNow:yyyyMMddHHmmssfff}_{Guid.NewGuid():N}.pfx";
        var rutaCompleta = Path.Combine(directorioCertificados, fileName);
        System.IO.File.WriteAllBytes(rutaCompleta, bytesPfx);
        return rutaCompleta;
    }

private static string ResolverRutaPfxDesdeArchivoOCarpeta(string valor)
    {
        if (System.IO.File.Exists(valor))
        {
            return valor;
        }

        if (Directory.Exists(valor))
        {
            var certificado = BuscarCertificadoEnDirectorio(valor);
            return string.IsNullOrWhiteSpace(certificado) ? valor : certificado;
        }

        if (Path.IsPathRooted(valor))
        {
            return valor;
        }

        var candidato = Path.Combine(ObtenerDirectorioCertificados(), valor);
        if (System.IO.File.Exists(candidato))
        {
            return candidato;
        }

        if (Directory.Exists(candidato))
        {
            var certificado = BuscarCertificadoEnDirectorio(candidato);
            return string.IsNullOrWhiteSpace(certificado) ? candidato : certificado;
        }

        return valor;
    }

private static Dictionary<string, string>? CrearRespuestaCertificadoInvalidoSiCorresponde(string? rutaOriginal, string rutaNormalizada)
    {
        if (System.IO.File.Exists(rutaNormalizada))
        {
            return null;
        }

        var original = string.IsNullOrWhiteSpace(rutaOriginal) ? "(vacío)" : rutaOriginal.Trim();
        var mensaje = $"No se pudo encontrar el certificado PFX/P12 desde '{original}'. Ruta resuelta: '{rutaNormalizada}'. Verifica la configuración CPE de la compañía y que el archivo exista en la carpeta CPE del servidor.";

        return new Dictionary<string, string>
        {
            ["flg_rta"] = "0",
            ["mensaje"] = mensaje,
            ["cod_sunat"] = string.Empty,
            ["msj_sunat"] = mensaje,
            ["hash_cpe"] = string.Empty,
            ["hash_cdr"] = string.Empty,
            ["cdr_base64"] = string.Empty
        };
    }

private static string BuscarCertificadoEnDirectorio(string directorio)
    {
        try
        {
            return Directory
                .EnumerateFiles(directorio, "*.*", SearchOption.AllDirectories)
                .FirstOrDefault(path =>
                    path.EndsWith(".pfx", StringComparison.OrdinalIgnoreCase) ||
                    path.EndsWith(".p12", StringComparison.OrdinalIgnoreCase)) ?? string.Empty;
        }
        catch
        {
            return string.Empty;
        }
    }

private static bool TryObtenerBytesDesdeBase64(string valor, out byte[] bytes)
    {
        bytes = Array.Empty<byte>();
        var candidato = valor.Trim();

        const string marcadorBase64 = "base64,";
        var indiceMarcador = candidato.IndexOf(marcadorBase64, StringComparison.OrdinalIgnoreCase);
        if (candidato.StartsWith("data:", StringComparison.OrdinalIgnoreCase) && indiceMarcador >= 0)
        {
            candidato = candidato[(indiceMarcador + marcadorBase64.Length)..];
        }

        candidato = candidato.Replace("\r", string.Empty).Replace("\n", string.Empty).Trim();

        if (candidato.EndsWith(".pfx", StringComparison.OrdinalIgnoreCase) ||
            candidato.EndsWith(".p12", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        if (candidato.Length < 128 || !EsCadenaBase64(candidato))
        {
            return false;
        }

        try
        {
            if (candidato.Length % 4 != 0)
            {
                candidato = candidato.PadRight(candidato.Length + (4 - (candidato.Length % 4)), '=');
            }

            bytes = Convert.FromBase64String(candidato);
            return bytes.Length > 0;
        }
        catch
        {
            return false;
        }
    }

private static bool EsCadenaBase64(string value)
    {
        for (int i = 0; i < value.Length; i++)
        {
            var ch = value[i];
            if ((ch >= 'A' && ch <= 'Z') ||
                (ch >= 'a' && ch <= 'z') ||
                (ch >= '0' && ch <= '9') ||
                ch == '+' || ch == '/' || ch == '=')
            {
                continue;
            }
            return false;
        }
        return true;
    }

