            return preferido;
        }
        catch
        {
            var fallback = Path.Combine(AppContext.BaseDirectory, "legacy-cpe", "FIRMABETA");
            Directory.CreateDirectory(fallback);
            return fallback;
        }
    }

private static IReadOnlyList<PagoVariosItemResponse> ParsePagoVariosItems(string raw)
    {
        var rows = (raw ?? string.Empty).Split('¬').Skip(3);
        var items = new List<PagoVariosItemResponse>();

        foreach (var row in rows)
        {
            if (string.IsNullOrWhiteSpace(row) || row.TrimStart().StartsWith("~", StringComparison.Ordinal))
                break;

            var values = row.Split('|');
            static string Get(string[] values, int index)
                => index >= 0 && index < values.Length ? values[index].Trim() : string.Empty;

            if (!long.TryParse(Get(values, 0), NumberStyles.Any, CultureInfo.InvariantCulture, out var docuId))
                continue;
            if (!long.TryParse(Get(values, 1), NumberStyles.Any, CultureInfo.InvariantCulture, out var notaId))
                continue;

            decimal.TryParse(Get(values, 5), NumberStyles.Number, CultureInfo.GetCultureInfo("en-US"), out var monto);
            items.Add(new PagoVariosItemResponse
            {
                DocuId = docuId,
                NotaId = notaId,
                Documento = Get(values, 2),
                Codigo = Get(values, 3),
                RazonSocial = Get(values, 4),
                Monto = monto,
                ConceptoOBS = Get(values, 7)
            });
        }

        return items;
    }

private static async Task<IReadOnlyList<PagoVariosItemResponse>> ListarPagoVariosPendientesDirectoAsync(
        SqlConnection con,
        string? usuario,
        CancellationToken cancellationToken)
    {
        var user = (usuario ?? string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(user))
            return Array.Empty<PagoVariosItemResponse>();

        await using var cmd = new SqlCommand("""
            SELECT
                d.DocuId,
                n.NotaId,
                LTRIM(RTRIM(ISNULL(d.DocuSerie, ''))) + '-' + LTRIM(RTRIM(ISNULL(d.DocuNumero, ''))) AS Documento,
                ISNULL(c.ClienteCodigo, '') AS Codigo,
                ISNULL(c.ClienteRazon, '') AS RazonSocial,
                ISNULL(n.NotaPagar, n.NotaTotal) AS Monto,
                ISNULL(n.ConceptoOBS, '') AS ConceptoOBS
            FROM NotaPedido n
            INNER JOIN DocumentoVenta d ON d.NotaId = n.NotaId
            INNER JOIN Cliente c ON c.ClienteId = n.ClienteId
            WHERE LTRIM(RTRIM(ISNULL(n.NotaCondicion, ''))) = 'PAGO/VARIOS'
              AND LTRIM(RTRIM(ISNULL(n.NotaEstado, ''))) NOT IN ('CANCELADO', 'ANULADO')
              AND LTRIM(RTRIM(ISNULL(n.NotaUsuario, ''))) = @Usuario
              AND NOT EXISTS (SELECT 1 FROM DetallePVarios dp WHERE dp.NotaId = n.NotaId)
            ORDER BY n.NotaId DESC;
            """, con);
        cmd.Parameters.AddWithValue("@Usuario", user);

        var items = new List<PagoVariosItemResponse>();
        await using var reader = await cmd.ExecuteReaderAsync(cancellationToken);
        while (await reader.ReadAsync(cancellationToken))
        {
            items.Add(new PagoVariosItemResponse
            {
                DocuId = Convert.ToInt64(reader["DocuId"], CultureInfo.InvariantCulture),
                NotaId = Convert.ToInt64(reader["NotaId"], CultureInfo.InvariantCulture),
                Documento = reader["Documento"]?.ToString()?.Trim() ?? string.Empty,
                Codigo = reader["Codigo"]?.ToString()?.Trim() ?? string.Empty,
                RazonSocial = reader["RazonSocial"]?.ToString()?.Trim() ?? string.Empty,
                Monto = Convert.ToDecimal(reader["Monto"], CultureInfo.InvariantCulture),
                ConceptoOBS = reader["ConceptoOBS"]?.ToString()?.Trim() ?? string.Empty
            });
        }

        return items;
    }

private static bool TryObtenerRangoDesdeData(string data, out DateTime fechaInicio, out DateTime fechaFin, out string? error)
    {
        fechaInicio = default;
        fechaFin = default;
        error = null;

        var partes = data.Split('|');
        if (partes.Length == 0 || string.IsNullOrWhiteSpace(partes[0]))
        {
            error = "Data inválido. Formato esperado: MM/dd/yyyy|MM/dd/yyyy.";
            return false;
        }

        var formatos = new[] { "MM/dd/yyyy", "M/d/yyyy", "dd/MM/yyyy", "d/M/yyyy", "yyyy-MM-dd", "yyyy/MM/dd" };
        if (!DateTime.TryParseExact(
                partes[0].Trim(),
                formatos,
                CultureInfo.InvariantCulture,
                DateTimeStyles.None,
                out var fechaInicioTmp)
            && !DateTime.TryParse(partes[0].Trim(), CultureInfo.InvariantCulture, DateTimeStyles.None, out fechaInicioTmp))
        {
            error = "No se pudo interpretar la fecha inicial en Data.";
            return false;
        }

        var fechaFinTmp = fechaInicioTmp;
        if (partes.Length > 1 && !string.IsNullOrWhiteSpace(partes[1]))
        {
            if (!DateTime.TryParseExact(
                    partes[1].Trim(),
                    formatos,
                    CultureInfo.InvariantCulture,
                    DateTimeStyles.None,
                    out fechaFinTmp)
                && !DateTime.TryParse(partes[1].Trim(), CultureInfo.InvariantCulture, DateTimeStyles.None, out fechaFinTmp))
            {
                error = "No se pudo interpretar la fecha final en Data.";
                return false;
            }
        }

        if (fechaInicioTmp.Date > fechaFinTmp.Date)
        {
            error = "La fecha inicial no puede ser mayor que la fecha final.";
            return false;
        }

        fechaInicio = fechaInicioTmp.Date;
        fechaFin = fechaFinTmp.Date;
        return true;
    }

[HttpGet]
    public async Task<IActionResult> Listar(
        [FromQuery] DateOnly fechaInicio,
        [FromQuery] DateOnly fechaFin,
        [FromQuery] string? tipoVenta,
        CancellationToken cancellationToken)
    {
        if (fechaInicio > fechaFin)
            return BadRequest(new { ok = false, mensaje = "La fecha inicio no puede ser mayor que la fecha fin." });

        var connectionString = _configuration.GetConnectionString("DefaultConnection");
        if (string.IsNullOrWhiteSpace(connectionString))
            return StatusCode(500, new { ok = false, mensaje = "No se encontró la cadena de conexión." });

        var tipo = NormalizarTipo(tipoVenta);
        var items = new List<ObsCaptureRow>();
        await using var con = new SqlConnection(connectionString);
        await using var cmd = new SqlCommand("""
            SELECT T.ID, CONVERT(char(10), T.FechaTransaccion, 23) AS Fecha,
                   T.NotaTransaccion, T.CodigoMiembro, T.NombreMiembro, T.Importe,
                   ISNULL(N.NotaUsuario, 'NO EXISTE') AS Usuario,
                   ISNULL(N.NotaEstado, 'NO EXISTE') AS Estado,
                   ISNULL(CONVERT(varchar(30), N.CajaId), 'NO EXISTE') AS CajaId
              FROM TABLAOBS T
              LEFT JOIN NotaPedido N ON N.NotaTransaccion = T.NotaTransaccion
             WHERE T.TipoVenta = @TipoVenta
               AND T.FechaTransaccion BETWEEN @FechaInicio AND @FechaFin
             ORDER BY T.FechaTransaccion, T.ID;
            """, con);
        cmd.Parameters.Add("@FechaInicio", SqlDbType.Date).Value = fechaInicio.ToDateTime(TimeOnly.MinValue);
        cmd.Parameters.Add("@FechaFin", SqlDbType.Date).Value = fechaFin.ToDateTime(TimeOnly.MinValue);
        cmd.Parameters.Add("@TipoVenta", SqlDbType.NVarChar, 3).Value = tipo;

        await con.OpenAsync(cancellationToken);
        await using var reader = await cmd.ExecuteReaderAsync(cancellationToken);
        while (await reader.ReadAsync(cancellationToken))
        {
            items.Add(new ObsCaptureRow(
                Convert.ToInt64(reader["ID"], CultureInfo.InvariantCulture),
                reader["Fecha"]?.ToString() ?? string.Empty,
                reader["NotaTransaccion"]?.ToString() ?? string.Empty,
                reader["CodigoMiembro"]?.ToString() ?? string.Empty,
                reader["NombreMiembro"]?.ToString() ?? string.Empty,
                Convert.ToDecimal(reader["Importe"], CultureInfo.InvariantCulture),
                reader["Usuario"]?.ToString() ?? string.Empty,
                reader["Estado"]?.ToString() ?? string.Empty,
                reader["CajaId"]?.ToString() ?? string.Empty));
        }

        return Ok(items);
    }

[HttpPost]
    public async Task<IActionResult> Guardar(
        [FromBody] ObsCaptureRequest? request,
        CancellationToken cancellationToken)
    {
        var tipoSolicitado = NormalizarTipo(request?.TipoVenta);
        var lines = request?.Lines?
            .Where(line => line is not null)
            .Select(line => new ObsCaptureLine(
                line.Fecha,
                (line.NotaTransaccion ?? string.Empty).Trim(),
                (line.CodigoMiembro ?? string.Empty).Trim(),
                (line.NombreMiembro ?? string.Empty).Trim(),
                line.Importe))
            .Where(line => line.Fecha != default && line.NotaTransaccion.Length > 0 && line.Importe > 0)
            .GroupBy(line => line.NotaTransaccion, StringComparer.OrdinalIgnoreCase)
            .Select(group => group.Last())
            .ToList() ?? new List<ObsCaptureLine>();

        if (lines.Count == 0)
            return BadRequest(new { ok = false, mensaje = $"No se recibieron transacciones {tipoSolicitado} válidas." });
        var connectionString = _configuration.GetConnectionString("DefaultConnection");
        if (string.IsNullOrWhiteSpace(connectionString))
            return StatusCode(500, new { ok = false, mensaje = "No se encontró la cadena de conexión." });

        await using var con = new SqlConnection(connectionString);
        await con.OpenAsync(cancellationToken);
        await using var tx = (SqlTransaction)await con.BeginTransactionAsync(IsolationLevel.Serializable, cancellationToken);

        foreach (var line in lines)
        {
            var tipo = TipoPorTransaccion(line.NotaTransaccion);
            await using var cmd = new SqlCommand("""
                UPDATE TABLAOBS
                   SET FechaTransaccion = @Fecha,
                       CodigoMiembro = @Codigo,
                       NombreMiembro = @Miembro,
                       Importe = @Importe,
                       TipoVenta = @TipoVenta
                 WHERE NotaTransaccion = @Transaccion;
                IF @@ROWCOUNT = 0
                    INSERT INTO TABLAOBS
                        (FechaTransaccion, NotaTransaccion, CodigoMiembro, NombreMiembro, Importe, TipoVenta)
                    VALUES (@Fecha, @Transaccion, @Codigo, @Miembro, @Importe, @TipoVenta);
                """, con, tx);
            cmd.Parameters.Add("@Fecha", SqlDbType.Date).Value = line.Fecha.ToDateTime(TimeOnly.MinValue);
            cmd.Parameters.Add("@Transaccion", SqlDbType.VarChar, 250).Value = line.NotaTransaccion;
            cmd.Parameters.Add("@Codigo", SqlDbType.VarChar, 80).Value = line.CodigoMiembro;
            cmd.Parameters.Add("@Miembro", SqlDbType.NVarChar, 140).Value = line.NombreMiembro;
            cmd.Parameters.Add("@TipoVenta", SqlDbType.NVarChar, 3).Value = tipo;
            var importe = cmd.Parameters.Add("@Importe", SqlDbType.Decimal);
            importe.Precision = 18;
            importe.Scale = 2;
            importe.Value = line.Importe;
            await cmd.ExecuteNonQueryAsync(cancellationToken);
        }

        await tx.CommitAsync(cancellationToken);
        return Ok(new { ok = true, cantidad = lines.Count, mensaje = "Datos actualizados correctamente." });
    }

