private static void AddCajaId(SqlCommand cmd, long cajaId)
    {
        var parameter = cmd.Parameters.Add("@CajaId", SqlDbType.Decimal);
        parameter.Precision = 38;
        parameter.Scale = 0;
        parameter.Value = cajaId;
