private void IntentarGuardarXmlNotaCreditoPruebas(CPE cpe, Dictionary<string, string> respuesta)
    {
        try
        {
            var nombreArchivo = $"{cpe.NRO_DOCUMENTO_EMPRESA}-{cpe.COD_TIPO_DOCUMENTO}-{cpe.NRO_COMPROBANTE}";
            var rutaOrigen = CpeRutaResolver.ResolverRutaTrabajo(cpe.TIPO_PROCESO);
            var archivoOrigen = Path.Combine(rutaOrigen, nombreArchivo + ".XML");

            if (!File.Exists(archivoOrigen))
            {
                _logger.LogWarning(
                    "GuardarXmlNotaCredito activo, pero no se encontró el XML en {RutaXml}",
                    archivoOrigen);
                respuesta["xml_prueba_guardado"] = "false";
                respuesta["xml_prueba_mensaje"] = "No se encontró el XML firmado en la ruta de trabajo.";
                return;
            }

            var carpetaDestino = string.IsNullOrWhiteSpace(_pruebasSettings.RutaXmlNotaCredito)
                ? Path.Combine(AppContext.BaseDirectory, "xml-pruebas", "nota-credito")
                : _pruebasSettings.RutaXmlNotaCredito.Trim();

            Directory.CreateDirectory(carpetaDestino);
            var archivoDestino = Path.Combine(carpetaDestino, nombreArchivo + ".xml");
            File.Copy(archivoOrigen, archivoDestino, overwrite: true);

            respuesta["xml_prueba_guardado"] = "true";
            respuesta["xml_prueba_ruta"] = archivoDestino;

            _logger.LogInformation("XML de nota de crédito guardado para pruebas en {RutaXml}", archivoDestino);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "No se pudo guardar el XML de nota de crédito para pruebas.");
            respuesta["xml_prueba_guardado"] = "false";
            respuesta["xml_prueba_mensaje"] = ex.Message;
        }
    }

internal static string ResolverRutaTrabajo(int? tipoProceso)
    {
        var conexion = new Conexion();

        return tipoProceso switch
        {
            1 => ResolverRutaTrabajo(
                Environment.GetEnvironmentVariable("CPE_RUTA_PRODUCCION"),
                "\\\\" + conexion.ServidorIP + "\\ArchivoSistema\\CPE\\PRODUCCION\\",
                "PRODUCCION"),
            2 => ResolverRutaTrabajo(
                Environment.GetEnvironmentVariable("CPE_RUTA_HOMOLOGACION"),
                "D:\\CPE\\HOMOLOGACION\\",
                "HOMOLOGACION"),
            _ => ResolverRutaTrabajo(
                Environment.GetEnvironmentVariable("CPE_RUTA_BETA"),
                "\\\\" + conexion.ServidorIP + "\\ArchivoSistema\\CPE\\BETA\\",
                "BETA")
        };
    }

private static string ResolverRutaTrabajo(string? rutaOverride, string rutaPorDefecto, string carpetaFallback)
    {
        var rutaObjetivo = string.IsNullOrWhiteSpace(rutaOverride) ? rutaPorDefecto : rutaOverride.Trim();
        rutaObjetivo = AsegurarSlashFinal(rutaObjetivo);

        try
        {
            if (Directory.Exists(rutaObjetivo) || PuedeCrearDirectorio(rutaObjetivo))
            {
                Directory.CreateDirectory(rutaObjetivo);
                return rutaObjetivo;
            }
        }
        catch
        {
            // fallback local
        }

        var fallback = Path.Combine(AppContext.BaseDirectory, "legacy-cpe", carpetaFallback);
        Directory.CreateDirectory(fallback);
        return AsegurarSlashFinal(fallback);
    }

private static bool PuedeCrearDirectorio(string ruta)
    {
        try
        {
            Directory.CreateDirectory(ruta);
            return true;
        }
        catch
        {
            return false;
        }
    }

private static string AsegurarSlashFinal(string ruta)
    {
        if (string.IsNullOrWhiteSpace(ruta))
        {
            return ruta;
        }

        return ruta.EndsWith('\\') || ruta.EndsWith('/')
            ? ruta
            : ruta + Path.DirectorySeparatorChar;
    }

public async Task OnAuthorizationAsync(AuthorizationFilterContext context)
    {
        var method = context.HttpContext.Request.Method;
        if (HttpMethods.IsGet(method) || HttpMethods.IsHead(method) || HttpMethods.IsOptions(method))
            return;

        if (!int.TryParse(context.HttpContext.User.FindFirstValue("userId"), out var usuarioId) || usuarioId <= 0)
        {
            context.Result = new ForbidResult();
            return;
        }

        var connectionString = _configuration.GetConnectionString("DefaultConnection");
        if (string.IsNullOrWhiteSpace(connectionString))
        {
            context.Result = new ObjectResult(new { ok = false, mensaje = "No se encontró la cadena de conexión." })
            {
                StatusCode = StatusCodes.Status500InternalServerError
            };
            return;
        }

        await using var connection = new SqlConnection(connectionString);
        await connection.OpenAsync(context.HttpContext.RequestAborted);
        await using var command = new SqlCommand("""
            SELECT CASE
                     WHEN (
                         SELECT MAX(CASE WHEN ISNULL(i.ValorNum, 1) <> 0 THEN 1 ELSE 0 END)
                         FROM dbo.Usuarios AS u
                         INNER JOIN dbo.Personal AS p ON p.PersonalId = u.PersonalId
                         LEFT JOIN dbo.Indicador AS i
                           ON i.CompaniaId = p.CompaniaId
                          AND i.Descripcion = 'ASISTENCIA'
                         WHERE u.UsuarioID = @UsuarioId
                     ) = 0 THEN CAST(1 AS bit)
                     WHEN EXISTS
                     (
                         SELECT 1
                         FROM dbo.Asistencia AS a
                         INNER JOIN dbo.Usuarios AS u ON u.PersonalId = a.PersonalId
                         WHERE u.UsuarioID = @UsuarioId
                           AND a.Fecha = CONVERT(date, GETDATE())
                     ) THEN CAST(1 AS bit)
                     ELSE CAST(0 AS bit)
                   END;
            """, connection);
        command.Parameters.Add("@UsuarioId", System.Data.SqlDbType.Int).Value = usuarioId;

        var puedeContinuar = Convert.ToBoolean(
            await command.ExecuteScalarAsync(context.HttpContext.RequestAborted),
            System.Globalization.CultureInfo.InvariantCulture);
        if (!puedeContinuar)
        {
            context.Result = new ObjectResult(new
            {
                ok = false,
                codigo = "ASISTENCIA_REQUERIDA",
                mensaje = AttendanceMessage
            })
            {
                StatusCode = StatusCodes.Status409Conflict
            };
        }
    }

public async Task OnAuthorizationAsync(AuthorizationFilterContext context)
    {
        var user = context.HttpContext.User;
        if (user.Identity?.IsAuthenticated != true)
        {
            context.Result = new UnauthorizedResult();
            return;
        }

        if (user.HasClaim("isAdmin", "1")) return;

        if (!TryClaim(user, "userId", out var usuarioId) ||
            !TryClaim(user, "companiaId", out var companiaId) ||
            !TryClaim(user, "areaId", out var areaId))
        {
            context.Result = new ForbidResult();
            return;
        }

        var permisos = await _permisos.ObtenerEfectivosAsync(companiaId, areaId, usuarioId, context.HttpContext.RequestAborted);
        if (!permisos.Contains(_codigo, StringComparer.OrdinalIgnoreCase))
            context.Result = new ForbidResult();
    }

