public async Task<IReadOnlyList<EGeneral>> ListarAsync(int page = 1, int pageSize = 50, CancellationToken cancellationToken = default)
    {
        (page, pageSize) = NormalizePagination(page, pageSize);

        await using var con = new SqlConnection(_connectionString);
        await using var cmd = CrearComando(con, "LISTAR");
        await con.OpenAsync(cancellationToken);
        await using var reader = await cmd.ExecuteReaderAsync(cancellationToken);

        var areas = new List<EGeneral>();
        while (await reader.ReadAsync(cancellationToken))
        {
            var values = reader["Data"]?.ToString()?.Split('|', 2) ?? Array.Empty<string>();
            if (values.Length < 2 || string.IsNullOrWhiteSpace(values[0])) continue;
            areas.Add(new EGeneral { Id = values[0].Trim(), Nombre = values[1].Trim() });
        }

        return areas.Skip((page - 1) * pageSize).Take(pageSize).ToList();
    }

private async Task<string> EjecutarAsync(string data, CancellationToken cancellationToken)
    {
        await using var con = new SqlConnection(_connectionString);
        await using var cmd = CrearComando(con, data);
        await con.OpenAsync(cancellationToken);
        return (await cmd.ExecuteScalarAsync(cancellationToken))?.ToString()?.Trim() ?? string.Empty;
    }

private static SqlCommand CrearComando(SqlConnection con, string data)
    {
        var cmd = new SqlCommand("dbo.usp_Area", con)
        {
            CommandTimeout = 300,
            CommandType = CommandType.StoredProcedure
        };
        cmd.Parameters.Add("@Data", SqlDbType.VarChar, -1).Value = data;
        return cmd;
    }

private static (int page, int pageSize) NormalizePagination(int page, int pageSize)
    {
        var normalizedPage = page < 1 ? 1 : page;
        var normalizedPageSize = pageSize < 1 ? 1 : Math.Min(pageSize, 100);
        return (normalizedPage, normalizedPageSize);
    }

public async Task<string> InsertarAsync(Cliente cliente, CancellationToken cancellationToken = default)
    {
        var id = cliente.ClienteId;
        var razon = cliente.ClienteRazon?.Trim() ?? string.Empty;
        var ruc = cliente.ClienteRuc?.Trim() ?? string.Empty;
        var dni = cliente.ClienteDni?.Trim() ?? string.Empty;

        await using var con = new SqlConnection(_connectionString);
        await con.OpenAsync(cancellationToken);

        if (!string.IsNullOrWhiteSpace(ruc) && await DocumentoCambiadoYExisteAsync(con, "ClienteRuc", ruc, id, cancellationToken))
            return "existe RUC";

        await using var cmd = new SqlCommand
        {
            Connection = con,
            CommandTimeout = 300,
            CommandType = CommandType.Text,
            CommandText = id <= 0
                ? """
                  INSERT INTO Cliente
                    (ClienteRazon, ClienteRuc, ClienteDni, ClienteDireccion, ClienteMovil, ClienteTelefono,
                     ClienteCorreo, ClienteEstado, ClienteDespacho, ClienteCodigo, ClienteUsuario, ClienteFecha, ClienteDocu)
                  VALUES
                    (@Razon, @Ruc, @Dni, @Direccion, '', @Telefono, @Correo, @Estado, @Despacho,
                     @Codigo, @Usuario, GETDATE(), @Docu);
                  SELECT CONVERT(varchar(20), SCOPE_IDENTITY()) + '|' + @Razon;
                  """
                : """
                  UPDATE Cliente SET
                    ClienteRazon = @Razon,
                    ClienteRuc = @Ruc,
                    ClienteDni = @Dni,
                    ClienteDireccion = @Direccion,
                    ClienteTelefono = @Telefono,
                    ClienteCorreo = @Correo,
                    ClienteEstado = @Estado,
                    ClienteDespacho = @Despacho,
                    ClienteCodigo = @Codigo,
                    ClienteUsuario = @Usuario,
                    ClienteFecha = GETDATE(),
                    ClienteDocu = @Docu
                  WHERE ClienteId = @Id;
                  SELECT CONVERT(varchar(20), @Id) + '|' + @Razon;
                  """
        };

        cmd.Parameters.AddWithValue("@Id", id);
        cmd.Parameters.AddWithValue("@Razon", razon);
        cmd.Parameters.AddWithValue("@Ruc", ruc);
        cmd.Parameters.AddWithValue("@Dni", dni);
        cmd.Parameters.AddWithValue("@Direccion", cliente.ClienteDireccion?.Trim() ?? string.Empty);
        cmd.Parameters.AddWithValue("@Telefono", cliente.ClienteTelefono?.Trim() ?? string.Empty);
        cmd.Parameters.AddWithValue("@Correo", cliente.ClienteCorreo?.Trim() ?? string.Empty);
        cmd.Parameters.AddWithValue("@Estado", cliente.ClienteEstado?.Trim() ?? "ACTIVO");
        cmd.Parameters.AddWithValue("@Despacho", cliente.ClienteDespacho?.Trim() ?? string.Empty);
        cmd.Parameters.AddWithValue("@Codigo", cliente.ClienteCodigo?.Trim() ?? string.Empty);
        cmd.Parameters.AddWithValue("@Usuario", cliente.ClienteUsuario?.Trim() ?? string.Empty);
        cmd.Parameters.AddWithValue("@Docu", string.IsNullOrWhiteSpace(cliente.ClienteDocu) ? "BOLETA" : cliente.ClienteDocu.Trim());

        var result = (await cmd.ExecuteScalarAsync(cancellationToken))?.ToString();

