private static async Task<bool> DocumentoCambiadoYExisteAsync(SqlConnection con, string column, string value, long clienteId, CancellationToken cancellationToken)
    {
        await using var cmd = new SqlCommand(
            $"""
              SELECT TOP 1 1
              FROM Cliente
              WHERE LTRIM(RTRIM(ISNULL({column}, ''))) = @Value
                AND ClienteId <> @Id
                AND (@Id <= 0 OR ISNULL((SELECT TOP 1 LTRIM(RTRIM(ISNULL({column}, '')))
                                           FROM Cliente WHERE ClienteId = @Id), '') <> @Value);
              """,
            con);
        cmd.Parameters.AddWithValue("@Value", value);
        cmd.Parameters.AddWithValue("@Id", clienteId);
        return await cmd.ExecuteScalarAsync(cancellationToken) is not null;
    }

public async Task<bool> EliminarAsync(long id, CancellationToken cancellationToken = default)
    {
        if (id <= 0) return false;

        const string sql = "DELETE FROM Cliente WHERE ClienteId = @Id;";
        await using var con = new SqlConnection(_connectionString);
        await using var cmd = new SqlCommand(sql, con)
        {
            CommandTimeout = 300,
            CommandType = CommandType.Text
        };
        var idParam = cmd.Parameters.Add("@Id", SqlDbType.Decimal);
        idParam.Precision = 20;
        idParam.Scale = 0;
        idParam.Value = id;
        await con.OpenAsync(cancellationToken);
        if (!await ExisteClienteAsync(con, id, cancellationToken)) return false;

        try
        {
            var deleted = await cmd.ExecuteNonQueryAsync(cancellationToken);
            if (deleted <= 0) return false;
        }
        catch (SqlException)
        {
            return false;
        }

        return !await ExisteClienteAsync(con, id, cancellationToken);
    }

private static async Task<bool> ExisteClienteAsync(SqlConnection con, long id, CancellationToken cancellationToken)
    {
        await using var cmd = new SqlCommand("SELECT TOP 1 1 FROM Cliente WHERE ClienteId = @Id;", con);
        cmd.Parameters.AddWithValue("@Id", id);
        return await cmd.ExecuteScalarAsync(cancellationToken) is not null;
    }

public async Task<IReadOnlyList<Cliente>> ListarAsync(string? estado = "ACTIVO", string? search = null, int page = 1, int pageSize = 50, CancellationToken cancellationToken = default)
    {
        return (await ListarPaginadoAsync(estado, search, page, pageSize, cancellationToken)).Items;
    }

public async Task<ClienteListResult> ListarPaginadoAsync(string? estado = "ACTIVO", string? search = null, int page = 1, int pageSize = 50, CancellationToken cancellationToken = default, bool rucOnly = false)
    {
        (page, pageSize) = NormalizePagination(page, pageSize);
        var searchTerm = (search ?? string.Empty).Trim();
        var start = ((page - 1) * pageSize) + 1;
        var end = page * pageSize;

        const string sql = """
            WITH ClientesFiltrados AS (
                SELECT ClienteId, ClienteCodigo, ClienteRazon, ClienteRuc, ClienteDni, ClienteDireccion, ClienteTelefono,
                       ClienteCorreo, ClienteEstado, ClienteDespacho, ClienteUsuario, ClienteFecha, ClienteDocu,
                       COUNT(*) OVER() AS TotalRows,
                       ROW_NUMBER() OVER (ORDER BY ClienteRazon, ClienteId) AS RowNum
                FROM Cliente
                WHERE (@Estado IS NULL OR @Estado = '' OR ClienteEstado = @Estado)
                  AND (
                    @Search = ''
                    OR (@RucOnly = 1 AND ISNULL(ClienteRuc, '') LIKE @SearchLike)
                    OR (@RucOnly = 0 AND (
                        ISNULL(ClienteCodigo, '') LIKE @SearchLike
                        OR ISNULL(ClienteRazon, '') LIKE @SearchLike
                        OR ISNULL(ClienteRuc, '') LIKE @SearchLike
                        OR ISNULL(ClienteDni, '') LIKE @SearchLike
                    ))
                  )
            )
            SELECT ClienteId, ClienteCodigo, ClienteRazon, ClienteRuc, ClienteDni, ClienteDireccion, ClienteTelefono,
                   ClienteCorreo, ClienteEstado, ClienteDespacho, ClienteUsuario, ClienteFecha, ClienteDocu, TotalRows
            FROM ClientesFiltrados
            WHERE RowNum BETWEEN @Start AND @End
            ORDER BY RowNum;
            """;

        await using var con = new SqlConnection(_connectionString);
        await using var cmd = new SqlCommand(sql, con);
        cmd.Parameters.AddWithValue("@Estado", (object?)estado ?? DBNull.Value);
        cmd.Parameters.AddWithValue("@Search", searchTerm);
        cmd.Parameters.AddWithValue("@SearchLike", $"%{searchTerm}%");
        cmd.Parameters.AddWithValue("@RucOnly", rucOnly);
        cmd.Parameters.AddWithValue("@Start", start);
        cmd.Parameters.AddWithValue("@End", end);
        await con.OpenAsync(cancellationToken);
        await using var reader = await cmd.ExecuteReaderAsync(cancellationToken);

        var lista = new List<Cliente>();
        var total = 0;
        while (await reader.ReadAsync(cancellationToken))
        {
            total = Convert.ToInt32(reader["TotalRows"]);
            lista.Add(MapCliente(reader));
        }

        return new ClienteListResult { Items = lista, Total = total };
    }

