public async Task<IReadOnlyList<DetalleNota>> ListarDetalleAsync(long notaId, int page = 1, int pageSize = 50, CancellationToken cancellationToken = default)
    {
        (page, pageSize) = NormalizePagination(page, pageSize);
        const string sql = @"
            WITH Detalles AS (
                SELECT d.DetalleId,
                       d.NotaId,
                       d.IdProducto,
                       d.DetalleCantidad,
                       d.DetalleUm,
                       d.DetalleDescripcion,
                       d.DetalleCosto,
                       d.DetallePrecio,
                       ISNULL(d.DetalleCantidad, 0) * ISNULL(p.ProductoPV, 0) AS DetallePV,
                       ISNULL(d.DetalleCantidad, 0) * ISNULL(p.ProductoSV, 0) AS DetalleSV,
                       d.DetalleImporte,
                       d.DetalleEstado,
                       d.CantidadSaldo,
                       d.ValorUM,
                       ISNULL(NULLIF(p.ProductoINV, ''), 'S') AS AplicaINV,
                       ROW_NUMBER() OVER (ORDER BY d.DetalleId) AS RowNum
                FROM DetallePedido d
                LEFT JOIN Producto p ON p.IdProducto = d.IdProducto
                WHERE d.NotaId = @NotaId
            )
            SELECT DetalleId,
                   NotaId,
                   IdProducto,
                   DetalleCantidad,
                   DetalleUm,
                   DetalleDescripcion,
                   DetalleCosto,
                   DetallePrecio,
                   DetallePV,
                   DetalleSV,
                   DetalleImporte,
                   DetalleEstado,
                   CantidadSaldo,
                   ValorUM,
                   AplicaINV
            FROM Detalles
            WHERE RowNum BETWEEN @Offset + 1 AND @Offset + @PageSize
            ORDER BY RowNum;";

        await using var con = new SqlConnection(_connectionString);
        await using var cmd = new SqlCommand(sql, con);
        cmd.Parameters.AddWithValue("@NotaId", notaId);
        cmd.Parameters.AddWithValue("@Offset", (page - 1) * pageSize);
        cmd.Parameters.AddWithValue("@PageSize", pageSize);
        await con.OpenAsync(cancellationToken);
        await using var reader = await cmd.ExecuteReaderAsync(cancellationToken);
        var lista = new List<DetalleNota>();
        while (await reader.ReadAsync(cancellationToken))
        {
            lista.Add(MapDetalle(reader));
        }
        return lista;
    }

