        var action = id > 0 ? "ACTUALIZAR" : "CREAR";
        var values = new[]
        {
            action,
            id > 0 ? id.ToString(CultureInfo.InvariantCulture) : null,
            personal.PersonalNombres,
            personal.PersonalApellidos,
            personal.AreaId?.ToString(CultureInfo.InvariantCulture),
