    {
        (page, pageSize) = NormalizePagination(page, pageSize);

        const string sql = """
            SELECT ProveedorId, ProveedorRazon, ProveedorRuc, ProveedorContacto, ProveedorCelular,
                   ProveedorTelefono, ProveedorCorreo, ProveedorDireccion, ProveedorEstado
